import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { Tokenizer as HfTokenizer } from "@huggingface/tokenizers";
import { describe, expect, it } from "vitest";
import { openSourceModels } from "./index";
import { OpenSourceTokenizer, TiktokenTokenizer, type Tokenizer } from "./tokenizer";

// Compares the app's tokenizers with the Python references generated by
// scripts/parity.py. Skipped unless PARITY_DIR points at its output directory.
// The last corpus text is a 20,000-character CJK document used as the large-input case.
const dir = process.env.PARITY_DIR;
const suite = dir && existsSync(resolve(dir, "expected.json")) ? describe : describe.skip;
const LARGE_INPUT_BUDGET_MS = 5_000;
// Segment text of these models cannot rebuild the input: sentencepiece decoders normalize
// whitespace and "\u2581", and Whisper wraps every input in special tokens.
const LOSSY_DECODERS = new Set(["01-ai/Yi-6B", "openai/whisper-tiny"]);

// One character repeated hundreds of times can make byte-level BPE tokens straddle every
// character boundary, so segments cannot align within MAX_TOKENS_PER_SEGMENT. Counts are
// still checked for such texts, only the segment text round trip is skipped.
const isRepeatedChar = (text: string) => text.length > 100 && new Set(text).size === 1;

const read = <T>(file: string) => JSON.parse(readFileSync(resolve(dir ?? "", file), "utf8")) as T;

function loadOpenSource(repo: string): Tokenizer {
  const base = resolve(__dirname, "../../public/hf", repo);
  const json = JSON.parse(readFileSync(resolve(base, "tokenizer.json"), "utf8")) as object;
  const config = JSON.parse(readFileSync(resolve(base, "tokenizer_config.json"), "utf8")) as object;
  return new OpenSourceTokenizer(new HfTokenizer(json, config), repo);
}

function load(target: string): Tokenizer {
  return target.includes("/")
    ? loadOpenSource(target)
    : new TiktokenTokenizer(target as "o200k_base" | "cl100k_base");
}

suite("tokenizer parity with Python references", () => {
  const all = dir ? read<string[]>("corpus.json") : [];
  const expected = dir ? read<Record<string, number[][]>>("expected.json") : {};
  const targets = [...["o200k_base", "cl100k_base"], ...openSourceModels.options];
  const large = all.length - 1;

  it.each(targets)(
    "%s ids match",
    (target) => {
      const tokenizer = load(target);
      const reference = expected[target];
      expect(reference, `no reference for ${target}`).toBeDefined();

      const failures: string[] = [];
      for (let i = 0; i < large; i++) {
        const text = all[i]!;
        try {
          const result = tokenizer.tokenize(text);
          const actual = result.tokens;
          // TokenViewer shows the sum of segment token counts, so check that number too.
          const shown = result.segments?.reduce((n, s) => n + s.tokens.length, 0);
          if (JSON.stringify(actual) !== JSON.stringify(reference![i])) {
            failures.push(
              `#${i} ids differ (expected ${reference![i]!.length}, got ${actual.length}): ${JSON.stringify(text.slice(0, 40))}`
            );
          } else if (shown !== actual.length) {
            failures.push(
              `#${i} shown count ${shown} != ${actual.length}: ${JSON.stringify(text.slice(0, 40))}`
            );
          } else if (
            !LOSSY_DECODERS.has(target) &&
            !isRepeatedChar(text) &&
            result.segments?.map((s) => s.text).join("").normalize("NFC") !== text.normalize("NFC")
          ) {
            failures.push(`#${i} segments do not rebuild the text: ${JSON.stringify(text.slice(0, 40))}`);
          }
        } catch (err) {
          failures.push(`#${i} threw ${(err as Error).message}: ${JSON.stringify(text.slice(0, 40))}`);
        }
      }
      console.log(`${target}: ${large} texts, ${failures.length} failures`);
      expect(failures.slice(0, 10)).toEqual([]);
    },
    300_000
  );

  it.each(targets)(
    "%s large input within budget",
    (target) => {
      const tokenizer = load(target);
      const started = performance.now();
      const actual = tokenizer.tokenize(all[large]!).tokens;
      const elapsed = performance.now() - started;
      console.log(`${target}: large CJK input ${Math.round(elapsed)} ms, ${actual.length} tokens`);
      expect(actual).toEqual(expected[target]![large]);
      expect(elapsed).toBeLessThan(LARGE_INPUT_BUDGET_MS);
    },
    300_000
  );
});
